"""Render the owned-Emu80 NC profile campaign, without running an emulator."""
from pathlib import Path
import csv,json,statistics
ROOT=Path(__file__).resolve().parents[2]
OUT=ROOT/'docs/nc/main-bank-performance-2026-11-17'
def main():
 r=json.loads((OUT/'results.json').read_text(encoding='utf-8'))
 rows=r['rows'];assert len(rows)==8
 records={v['abi']['record_sha256'] for v in rows};indices={v['abi']['index_sha256'] for v in rows}
 assert len(records)==len(indices)==1
 med=lambda a:statistics.median(a)/2000
 def key(q,field,scroll):
  return med([v[field] for events in q['keys'].values() for v in events[2:] if v['scroll']==scroll])
 def find(font,profile):return next(q for q in rows if q['font']==font and q['profile']==profile)
 lines=['# MAIN и BANK NC: производительность в Emu80, 17 ноября 2026','',
 'Измерена зафиксированная сборка, находящаяся рядом в `build/`: BIOS, DOS, MEM, оба профиля NC, шрифты и образы. Emu80 исполнял Intel 8080 на 2 МГц; ВИ53 также 2 МГц, 16 банков RAM. Все значения ниже получены по счётчику `cpu_ticks`, а не по длительности HTTP-запросов. Это результаты эмулятора, не реального «Специалиста». Использовался собственный видимый экземпляр с отключёнными звуком ВИ53 и мониторингом ленты; после каждого опыта он закрывался. Чужие процессы и их образы не использовались.','',
 'Оба профиля получали одинаковый корень H: из 128 записей: 7 каталогов, 118 RKS, EXE, BAT и TXT. Сортировка — по расширению, одинаковые цвета и два файловых окна без F3. Совпадение исходных FILE_INFO и отсортированных индексов проверено SHA-256 для всех восьми опытов. Каталог преимущественно состоит из исполняемых файлов; отдельная сильно перемешанная цветовая выборка здесь не измерялась.','',
 'Для честного сравнения не использован H: на 250 записей: текущий MAIN с этими шрифтами вмещает 144 записи на каталог, BANK — 255. Packed6K уменьшает доступную MAIN ёмкость ещё сильнее, а Fast12K с текущей раскладкой обычного NC не помещается. Поэтому прямое сравнение сделано на Rotate, Compact, Fast8 и Cpm4 без нижних таблиц MAIN.','',
 '## Границы измерений','',
 f'- Запуск: от входа DOS в `keExternal`, до `getch2` после полного рисования панелей и выделения. Загрузка файла оболочки, а для BANK также CORE/GFX, подготовка каталогов и сортировка входят. Холодный означает новый экземпляр NC/отсутствие резидента; ОС уже запущена, её дисковый кэш не искусственно очищается. Набор команды и холодный bootstrap/AUTOEXEC не входят. Число запусков по шрифтам: {', '.join(font+' — '+str(min(len(q.get('startup_trials_ticks',[q['startup_ticks']])) for q in rows if q['font']==font)) for font in ['Rotate','Compact','Fast8','Cpm4'])}.','- Возврат CLI: от распознанного Enter команды EXIT до того же готового интерфейса NC. Учтены сохранение истории CLI, системный переход и рисование; MAIN перечитывается, BANK возобновляет CORE. Перед выходом выбирался корень H: и Home.','- Отзывчивость: клавиши передавались через `kbd_send`, команды набирались обычным редактором NC; PC/SP для интерфейсных опытов не менялись. Измерено движение после распознавания стрелки, отдельно от debounce и паузы автоповтора. Конец — следующий вход `getch2`, когда BANK уже выполнил накопленные команды MAIN.','- Удержание: настоящие press/release Up и Down, каждый раз проверялось изменение выбранного файла на один. Первый ответ и первый длинный интервал автоповтора исключены из установившихся медиан. Изменение firstFile определяет, была ли прокрутка.','- Текст: отдельный ABI-стенд вызывает производственный `printWholeFileList`, а для BANK также завершающий `ncBankFlush`. Входной каталог и индекс подготовлены заранее; получение списка DOS, сортировка, рамки и запуск исключены. Учитываются штатные цвета, очистка полей и вся банковая упаковка/пересылка. Более ранние команды UI сброшены до начала отсчёта.','- Каталог: один `DIR_OP_LIST` на 128 записей в буфер вызывающего профиля, включая драйвер H:, упаковку и FAR-доставку; без выбора диска/каталога, сортировки и рисования. Измерен повторный запрос с прогретым кэшем DOS.','- API-стенды выполнялись после нормального клавиатурного входа в нужный интерфейс. Только в этой отдельной фазе использовались временная обвязка и установка PC; после неё UI не возобновлялся. Для текста, каталога и сканера — три повтора.','',
 '## Rotate 6×8: основное сравнение','',
 '| Метрика | MAIN, мс | BANK, мс | BANK / MAIN |','|---|---:|---:|---:|']
 a=find('Rotate','MAIN');b=find('Rotate','BANK')
 metrics=[('Загрузка NC → готовые панели',a['startup_ticks']/2000,b['startup_ticks']/2000),('EXIT из CLI → готовые панели',a['cli_return_ticks']/2000,b['cli_return_ticks']/2000),('Стрелка из idle: нажатие → готовый кадр',statistics.mean(e[0]['interval_ticks'] for e in a['keys'].values())/2000,statistics.mean(e[0]['interval_ticks'] for e in b['keys'].values())/2000),('Распознанная стрелка → кадр без прокрутки',key(a,'render_ticks',False),key(b,'render_ticks',False)),('Распознанная стрелка → кадр с прокруткой',key(a,'render_ticks',True),key(b,'render_ticks',True)),('Удержание: интервал без прокрутки',key(a,'interval_ticks',False),key(b,'interval_ticks',False)),('Удержание: интервал с прокруткой',key(a,'interval_ticks',True),key(b,'interval_ticks',True)),('Вывод 38 имён панели',med(a['abi']['text_ticks']),med(b['abi']['text_ticks'])),('DIR_OP_LIST: 128 записей',med(a['abi']['list_ticks']),med(b['abi']['list_ticks']))]
 for label,x,y in metrics:lines.append(f'| {label} | {x:.2f} | {y:.2f} | {y/x:.2f}× |')
 lines+=['','Между распознаванием и следующим кадром BANK теряет примерно 37 мс на обычном движении. Интервал установившегося автоповтора дополнительно содержит около 21 мс штатного ожидания BIOS в обоих профилях. Первоначальная пауза автоповтора около половины секунды записана в raw-данных и не выдана за время отрисовки. Значение idle — от стандартной точки опроса до готового кадра, не средняя задержка при равномерно случайных фазах прихода клавиши.','',
 '## Остальные шрифты','',
 '| Шрифт | Профиль | Видимых имён | Запуск, мс | Возврат CLI, мс | Вывод панели, мс | Движение без прокрутки, мс | Прокрутка, мс |','|---|---|---:|---:|---:|---:|---:|---:|']
 for font in ['Rotate','Compact','Fast8','Cpm4']:
  for profile in ['MAIN','BANK']:
   q=find(font,profile)
   lines.append(f"| {font} | {profile} | {q['abi']['visible_names']} | {q['startup_ticks']/2000:.2f} | {q['cli_return_ticks']/2000:.2f} | {med(q['abi']['text_ticks']):.2f} | {key(q,'render_ticks',False):.2f} | {key(q,'render_ticks',True):.2f} |")
 lines+=['','Количество одновременно видимых имён отличается между геометриями: 38 для 6×8, 19 для 8×8 и 57 для 4×8. Поэтому строки разных шрифтов показывают стоимость реального интерфейса; их нельзя выдавать за одинаковый объём текста. MAIN/BANK внутри одного шрифта сравнивают одинаковый объём.','',
 '## Где BANK теряет время','',
 '| Участок обычного движения, Rotate | мс |','|---|---:|']
 for label,ticks in zip(b['pipeline']['labels'],b['pipeline']['ticks']):lines.append(f'| {label} | {ticks/2000:.2f} |')
 lines+=['','Точки разбиения: распознанная клавиша `loc_C311` → следующий CORE `ncBankGetch` → MAIN `ngBatch` → `ngSaveCursor` → MAIN `getch2`. Это один обычный шаг в начале списка, а не медиана всех имён. Собственно MAIN-отрисовка занимает около 17 мс, остальные примерно 39 мс — возврат клавиши, логика/упаковка, FAR и активация модулей.','',
 '## Клавиатура и локальный прототип','',
 'Текущий путь ожидания NC_BANK: CORE `ncBankGetch` → DOS `MODULE_CALL` → MAIN `NC_GFX.ngKey` → BIOS `getch2`. Внутренний цикл BIOS вызывает `keyScan2` напрямую и читает ВВ55; на каждый idle-опрос банк не переключается. Отдельный неблокирующий CORE `ncBankKeyScan` идёт через `MXOS_BIOS_KEY_SCAN` и адаптер IO в MAIN.','',
 '| Один неблокирующий опрос | Нет клавиш, мс | Нажата Down, мс |','|---|---:|---:|']
 for label,q,f1,f2 in [('MAIN → BIOS',a,'scan100_ticks','scan100_pressed_ticks'),('BANK: текущий путь NC',b,'scan100_ticks','scan100_pressed_ticks'),('Локальный сканер в EXEC, прототип',b,'scan100_local_ticks','scan100_local_pressed_ticks')]:
  lines.append(f"| {label} | {statistics.median(q['abi'][f1])/200000:.5f} | {statistics.median(q['abi'][f2])/200000:.5f} |")
 lines+=['','Для каждой серии из 100 вызовов показана медиана времени партии, делённая на 100. Локальный прототип использует тот же опрос матрицы из `source/io/key-scan.inc`, поиск кода из `source/bios/keyScan.inc` и копию текущей 96-байтной таблицы клавиатуры. Замер охватывает опрос и поиск кода клавиши. На разницу с прямым MAIN-входом влияет стоимость переходов к процедурам.','',
 'Вынос аппаратного сканера в платформенный хвост IO/MEM обоснован: неблокирующий опрос EXEC без клавиш ускоряется примерно в 35 раз. Приложения должны продолжать вызывать общий API; адреса ВВ55, раскладка матрицы и таблицы — задача системной реализации конкретной платформы. Нужно сохранить состояние раскладки и параметры клавиатуры, а не зашить в каждое приложение локальную копию аппаратного кода. Для NC переход на такой ввод позволит убрать часть переходов KEY, однако упаковку и доставку графики всё равно придётся ускорять отдельно.','',
 '## Вывод','',
 'Требование сохранить скорость MAIN пока не выполнено: BANK ощутимо медленнее при движении и печати во всех проверенных геометриях. Сортировка/получение списка не объясняют эту потерю. Выигрыш BANK — быстрый возврат резидента из CLI и освобождение MAIN для больших шрифтов; холодная загрузка пока дороже. Основная следующая цель оптимизации — граница CORE/GFX и число операций передачи, затем интеграция локального ввода в IO/MEM.','',
 'Сырые значения и SHA-256: [results.json](results.json). Измерительный скрипт: [benchmark-nc-profiles.py](../../../scripts/emu80/benchmark-nc-profiles.py). Таблицы построены [report-nc-profiles.py](../../../scripts/emu80/report-nc-profiles.py). Реальные аппаратные тайминги, flash-запись и совместимость сменных ядер этой серией не проверялись.','']
 (OUT/'report.md').write_text('\n'.join(lines),encoding='utf-8')
 with (OUT/'summary.csv').open('w',encoding='utf-8-sig',newline='') as f:
  out=csv.writer(f);out.writerow(['font','profile','startup_ms','cli_return_ms','text_ms','list_ms','move_ms','scroll_ms','hold_move_ms','hold_scroll_ms'])
  for q in rows:out.writerow([q['font'],q['profile'],q['startup_ticks']/2000,q['cli_return_ticks']/2000,med(q['abi']['text_ticks']),med(q['abi']['list_ticks']),key(q,'render_ticks',False),key(q,'render_ticks',True),key(q,'interval_ticks',False),key(q,'interval_ticks',True)])
 print(OUT/'report.md')
if __name__=='__main__':main()
